+    }
+    assert.deepEqual(await (await request(projectPath)).json(), { ...expected, archived: true });
+    await server.stop();
+    server = undefined;
+    server = await start(databasePath);
+    assert.deepEqual(await (await request(projectPath)).json(), { ...expected, archived: true });
